-- WAYS S platform foundation. Applied to the linked Supabase project as well.
alter table public.profiles add column if not exists is_verified boolean not null default false;
alter table public.profiles add column if not exists ways_verified boolean not null default false;
alter table public.profiles add column if not exists account_status text not null default 'active' check(account_status in ('active','suspended'));
create table if not exists public.follow_requests(id uuid primary key default gen_random_uuid(),requester_id uuid not null references public.profiles(id) on delete cascade,requested_id uuid not null references public.profiles(id) on delete cascade,status text not null default 'pending' check(status in ('pending','accepted','declined')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(requester_id,requested_id),check(requester_id<>requested_id));
alter table public.follow_requests enable row level security;
drop policy if exists "participants read follow requests" on public.follow_requests;
create policy "participants read follow requests" on public.follow_requests for select to authenticated using(auth.uid()=requester_id or auth.uid()=requested_id);
drop policy if exists "requesters create follow requests" on public.follow_requests;
create policy "requesters create follow requests" on public.follow_requests for insert to authenticated with check(auth.uid()=requester_id and status='pending');
drop policy if exists "recipients update follow requests" on public.follow_requests;
create policy "recipients update follow requests" on public.follow_requests for update to authenticated using(auth.uid()=requested_id) with check(auth.uid()=requested_id and status in ('accepted','declined'));
drop policy if exists "participants delete follow requests" on public.follow_requests;
create policy "participants delete follow requests" on public.follow_requests for delete to authenticated using(auth.uid()=requester_id or auth.uid()=requested_id);
create table if not exists public.profile_blocks(id uuid primary key default gen_random_uuid(),blocker_id uuid not null references public.profiles(id) on delete cascade,blocked_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),unique(blocker_id,blocked_id),check(blocker_id<>blocked_id));
alter table public.profile_blocks enable row level security;
drop policy if exists "users manage own blocks" on public.profile_blocks;
create policy "users manage own blocks" on public.profile_blocks for all to authenticated using(auth.uid()=blocker_id) with check(auth.uid()=blocker_id);
create table if not exists public.profile_reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id) on delete cascade,reported_id uuid not null references public.profiles(id) on delete cascade,reason text not null,status text not null default 'open' check(status in ('open','reviewing','resolved','dismissed')),created_at timestamptz not null default now(),check(reporter_id<>reported_id));
alter table public.profile_reports enable row level security;
drop policy if exists "users create reports" on public.profile_reports;
create policy "users create reports" on public.profile_reports for insert to authenticated with check(auth.uid()=reporter_id);
drop policy if exists "reporters read own reports" on public.profile_reports;
create policy "reporters read own reports" on public.profile_reports for select to authenticated using(auth.uid()=reporter_id);
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
alter table public.admin_users enable row level security;
drop policy if exists "admins can read admin roster" on public.admin_users;
create policy "admins can read admin roster" on public.admin_users for select to authenticated using(exists(select 1 from public.admin_users a where a.user_id=auth.uid()));
insert into public.admin_users(user_id) select id from auth.users where lower(email)='vikashjagarwal08@gmail.com' on conflict do nothing;
create or replace function public.bootstrap_wayss_admin() returns trigger language plpgsql security definer set search_path=public,auth as $$ begin if lower(coalesce(new.email,''))='vikashjagarwal08@gmail.com' then insert into public.admin_users(user_id) values(new.id) on conflict do nothing; end if; return new; end; $$;
drop trigger if exists wayss_admin_bootstrap on auth.users;
create trigger wayss_admin_bootstrap after insert on auth.users for each row execute procedure public.bootstrap_wayss_admin();
create table if not exists public.verification_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,request_type text not null default 'verified' check(request_type in ('verified','ways')),details text not null default '',status text not null default 'pending' check(status in ('pending','approved','rejected')),reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now());
alter table public.verification_requests enable row level security;
drop policy if exists "users manage own verification requests" on public.verification_requests;
create policy "users manage own verification requests" on public.verification_requests for select to authenticated using(auth.uid()=user_id);
drop policy if exists "users submit verification requests" on public.verification_requests;
create policy "users submit verification requests" on public.verification_requests for insert to authenticated with check(auth.uid()=user_id and status='pending');
drop policy if exists "admins manage verification requests" on public.verification_requests;
create policy "admins manage verification requests" on public.verification_requests for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=auth.uid())) with check(exists(select 1 from public.admin_users a where a.user_id=auth.uid()));
create table if not exists public.stories(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,media_url text not null,media_type text not null check(media_type in ('image','video')),caption text,expires_at timestamptz not null default(now()+interval '24 hours'),created_at timestamptz not null default now());
alter table public.stories enable row level security;
drop policy if exists "visible stories from followed or public users" on public.stories;
create policy "visible stories from followed or public users" on public.stories for select to authenticated using(expires_at>now() and exists(select 1 from public.profiles p where p.id=user_id and (p.id=auth.uid() or not p.is_private or exists(select 1 from public.follows f where f.follower_id=auth.uid() and f.following_id=p.id))) and not exists(select 1 from public.profile_blocks b where (b.blocker_id=auth.uid() and b.blocked_id=user_id) or (b.blocker_id=user_id and b.blocked_id=auth.uid())));
drop policy if exists "users manage own stories" on public.stories;
create policy "users manage own stories" on public.stories for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
alter table public.messages add column if not exists media_url text;
alter table public.messages add column if not exists message_type text not null default 'text';
alter table public.messages add column if not exists read_at timestamptz;
alter table public.messages add column if not exists deleted_for_sender boolean not null default false;
alter table public.messages add column if not exists deleted_for_receiver boolean not null default false;
create table if not exists public.voice_video_calls(id uuid primary key default gen_random_uuid(),caller_id uuid not null references public.profiles(id) on delete cascade,callee_id uuid not null references public.profiles(id) on delete cascade,call_type text not null check(call_type in ('voice','video')),status text not null default 'ringing' check(status in ('ringing','accepted','rejected','ended','missed','failed')),started_at timestamptz not null default now(),answered_at timestamptz,ended_at timestamptz,created_at timestamptz not null default now(),check(caller_id<>callee_id));
alter table public.voice_video_calls enable row level security;
drop policy if exists "call participants access calls" on public.voice_video_calls;
create policy "call participants access calls" on public.voice_video_calls for select to authenticated using(auth.uid()=caller_id or auth.uid()=callee_id);
drop policy if exists "caller starts calls" on public.voice_video_calls;
create policy "caller starts calls" on public.voice_video_calls for insert to authenticated with check(auth.uid()=caller_id);
drop policy if exists "callee or caller updates calls" on public.voice_video_calls;
create policy "callee or caller updates calls" on public.voice_video_calls for update to authenticated using(auth.uid()=caller_id or auth.uid()=callee_id) with check(auth.uid()=caller_id or auth.uid()=callee_id);
create or replace function public.is_username_available(candidate text) returns boolean language sql stable security invoker set search_path=public as $$ select candidate ~ '^[a-z0-9_]{3,30}$' and not exists(select 1 from public.profiles p where lower(p.username)=lower(candidate)); $$;
grant execute on function public.is_username_available(text) to anon,authenticated;
